{"security_risk":"LOW","summary":"Create package info module","command":"create","path":"/workspace/src/rs/package_info.rs","file_text":"use std::fs;
use std::path::{Path, PathBuf};

use serde_json::Value;

/// Read a JSON value from a file next to the executable's package root.
pub fn read_package_json(root: &Path) -> Option<Value> {
    let pkg_path = root.join("package.json");
    let raw = fs::read_to_string(&pkg_path).ok()?;
    serde_json::from_str(&raw).ok()
}

/// Find the package root by walking up from the executable until a package.json
/// is found whose `name` field matches `jscodeshift`.
pub fn locate_package_root(start: &Path) -> Option<PathBuf> {
    let mut dir = if start.is_file() {
        start.parent()?.to_path_buf()
    } else {
        start.to_path_buf()
    };
    loop {
        let candidate = dir.join("package.json");
        if candidate.is_file() {
            if let Ok(raw) = fs::read_to_string(&candidate) {
                if let Ok(value) = serde_json::from_str::<Value>(&raw) {
                    if value.get("name").and_then(|v| v.as_str()) == Some("jscodeshift") {
                        return Some(dir);
                    }
                }
            }
        }
        if !dir.pop() {
            return None;
        }
    }
}

/// Return the package's declared version (defaults to "unknown").
pub fn package_version(root: &Path) -> String {
    read_package_json(root)
        .and_then(|v| v.get("version").and_then(|v| v.as_str().map(|s| s.to_owned())))
        .unwrap_or_else(|| "unknown".to_owned())
}

/// Return the dependencies block as a parsed JSON value, or null if missing.
pub fn package_dependencies(root: &Path) -> Value {
    read_package_json(root)
        .and_then(|v| v.get("dependencies").cloned())
        .unwrap_or(Value::Null)
}"}

