pub fn dim(text: &str) -> String { wrap(DIM, text) }
pub fn bold(text: &str) -> String { wrap(BOLD, text) }

pub fn bg_red(text: &str) -> String { wrap(BG_RED, text) }
pub fn bg_green(text: &str) -> String { wrap(BG_GREEN, text) }
pub fn bg_yellow(text: &str) -> String { wrap(BG_YELLOW, text) }
pub fn bg_magenta(text: &str) -> String { wrap(BG_MAGENTA, text) }
pub fn bg_cyan(text: &str) -> String { wrap(BG_CYAN, text) }
