//!
//! The Rust CLI parses argv by hand to faithfully reproduce the behavior of
//! `src/argsParser.js`, including the help text, error messages, and option
//! formatting that the JavaScript version exposed.

use std::fmt;

/// Fully resolved CLI options. Mirrors the keys returned by the original
/// `argsParser` so the JavaScript bridge (and downstream consumers) see the
/// exact same shape.
#[derive(Debug, Clone)]
pub struct Options {
    pub transform: Option<String>,
    pub paths: Vec<String>,
    pub extensions: Vec<String>,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub run_in_band: bool,
    pub worker_count: Option<usize>,
    pub cpus: usize,
    pub verbose: u8,
    pub dry: bool,
    pub print: bool,
    pub babel: bool,
    pub extensions_only: bool,
    pub parser: String,
    pub parser_options: Option<String>,
    pub transform_options: String,
    pub run_async: bool,
    pub stdin: bool,
    pub gitignore: bool,
    pub help: bool,
    pub version: bool,
}

impl Default for Options {
    fn default() -> Self {
        let cpus = std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1);
        Options {
            transform: None,
            paths: vec![],
            extensions: vec![
                "js".into(), "mjs".into(), "cjs".into(), "jsx".into(),
                "ts".into(), "tsx".into(),
            ],
            ignore_pattern: vec![],
            ignore_config: vec![],
            run_in_band: false,
            worker_count: None,
            cpus,
            verbose: 0,
            dry: false,
            print: false,
            babel: false,
            extensions_only: false,
            parser: "babel".into(),
            parser_options: None,
            transform_options: "{}".into(),
            run_async: false,
            stdin: false,
            gitignore: false,
            help: false,
            version: false,
        }
    }
}

#[derive(Clone, Debug)]
pub struct OptionSpec {
    pub name: &'static str,
    pub short: Option<char>,
    pub long: &'static str,
