        default: None,
    },
];

pub fn find_spec(name: &str) -> Option<&'static OptionSpec> {
    OPTIONS.iter().find(|o| o.name == name)
}

pub fn find_spec_by_long(long: &str) -> Option<&'static OptionSpec> {
    OPTIONS.iter().find(|o| o.long == long)
}

pub fn find_spec_by_short(short: char) -> Option<&'static OptionSpec> {
    OPTIONS.iter().find(|o| o.short == Some(short))
}

/// Format an option for the help banner, matching the original argsParser
/// format (`-x, --xyy=VALUE` / `-x, --xyy`).
pub fn format_option(spec: &OptionSpec) -> String {
    let short = spec.short.map(|c| format!("-{}", c)).unwrap_or_default();
    let long = match spec.arg {
        Some(_) => format!("--{}=", spec.long),
        None => format!("--{}", spec.long),
    };
    match spec.arg {
        Some(arg) => match short.is_empty() {
            true => format!("    {}={}", long, arg.to_uppercase()),
            false => format!("{}, {}={}", short, long, arg.to_uppercase()),
        },
        None => match short.is_empty() {
            true => format!("    {}", long),
            false => format!("{}, {}", short, long),
        },
    }
}

pub fn build_help() -> String {
    let mut out = String::from("Usage: jscodeshift [OPTION]... PATH... [FILE...]\n\nOptions:\n");
    let mut specs: Vec<&OptionSpec> = OPTIONS.iter().collect();
    specs.sort_by_key(|s| s.name);
    for spec in specs {
        out.push_str(&format!("  {:<32} {}\n", format_option(spec), spec.description));
    }
    out.push_str("\n  PATH     Files or directories to transform.\n");
    out.push_str("  FILE     File contents to read from stdin (use --stdin).\n");
    out
}

/// Parser error carrying an exit code and the message to display.
#[derive(Debug)]
pub struct ParseError {
    pub code: i32,
    pub message: String,
    pub help: bool,
}

impl ParseError {
    pub fn new(code: i32, message: impl Into<String>) -> Self {
        ParseError { code, message: message.into(), help: false }
    }
    pub fn with_help(mut self) -> Self { self.help = true; self }
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.message)
    }
}"}

{"security_risk":"LOW","summary":"Create CLI parser module","command":"create","path":"/workspace/src/rs/cli.rs","file_text":"//! Hand-rolled CLI parser that mirrors `src/argsParser.js`.
//!
//! Supports short/long flags, attached (`-xvalue`), glued (`-xv`), and
//! `=`-separated values, plus the same defaults the JavaScript version
//! applied.

use crate::options::{
    build_help, find_spec_by_long, find_spec_by_short, Options, ParseError,
};

pub fn parse(argv: &[String]) -> Result<Options, ParseError> {
    let mut opts = Options::default();
    let mut iter = argv.iter().enumerate().peekable();

    let mut set_value = |opts: &mut Options, spec_name: &str, value: Option<String>| -> Result<(), ParseError> {
        match spec_name {
            "transform" => opts.transform = value,
            "extensions" => {
                if let Some(v) = value {
                    opts.extensions = v.split(',').map(|s| s.trim().to_owned()).filter(|s| !s.is_empty()).collect();
                }
            }
            "parser" => {
                if let Some(v) = value {
                    opts.parser = v;
                }
            }
            "parser-options" => opts.parser_options = value,
            "transform-options" => {
                if let Some(v) = value {
                    opts.transform_options = v;
                }
            }
            "ignore-pattern" => {
                if let Some(v) = value {
                    opts.ignore_pattern = v.split(',').map(|s| s.trim().to_owned()).filter(|s| !s.is_empty()).collect();
                }
            }
            "ignore-config" => {
                if let Some(v) = value {
                    opts.ignore_config = v.split(',').map(|s| s.trim().to_owned()).filter(|s| !s.is_empty()).collect();
                }
            }
            "cpus" => {
                if let Some(v) = value {
                    opts.cpus = v.parse::<usize>().map_err(|_| ParseError::new(1, format!("--cpus must be an integer, got '{}'", v)))?;
                    if opts.cpus == 0 {
                        opts.cpus = std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1);
                    }
                }
            }
            "worker" => {
                if let Some(v) = value {
                    opts.worker_count = Some(v.parse::<usize>().map_err(|_| ParseError::new(1, format!("--worker must be an integer, got '{}'", v)))?);
                }
            }
            "verbose" => {
                if let Some(v) = value {
                    opts.verbose = v.parse::<u8>().map_err(|_| ParseError::new(1, format!("--verbose must be an integer, got '{}'", v)))?;
                } else {
                    opts.verbose = 1;
                }
            }
            "help" => opts.help = true,
            "version" => opts.version = true,
            _ => return Err(ParseError::new(1, format!("Unknown option '{}'", spec_name))),
        }
        Ok(())
    };

    while let Some((_idx, arg)) = iter.next() {
        if arg == "--" {
            // Everything after `--` is positional.
            while let Some((_, v)) = iter.next() {
                opts.paths.push(v.clone());
            }
            break;
        }
        if let Some(rest) = arg.strip_prefix("--") {
            // Long option.
            let (name, attached) = match rest.split_once('=') {
                Some((n, v)) => (n.to_owned(), Some(v.to_owned())),
                None => (rest.to_owned(), None),
            };
            let spec = find_spec_by_long(&name)
                .ok_or_else(|| ParseError::new(1, format!("Unknown option --{}", name)))?
                .clone();
            let value = match spec.arg {
                Some(_) => {
                    if let Some(v) = attached {
                        Some(v)
                    } else if let Some((_, next)) = iter.next() {
                        Some(next.clone())
                    } else {
                        return Err(ParseError::new(1, format!("--{} requires a value", spec.long)));
                    }
                }
                None => {
                    if attached.is_some() {
                        return Err(ParseError::new(1, format!("--{} does not take a value", spec.long)));
                    }
                    Some("true".into())
                }
            };
            set_value(&mut opts, spec.name, value)?;
        } else if let Some(short_part) = arg.strip_prefix('-') {
            if short_part.is_empty() {
                // `-` on its own: treat as positional so paths starting with
                // `-` after a `--` separator still work.
                opts.paths.push(arg.clone());
                continue;
            }
            // Could be `-abc` (booleans) or `-xVALUE` (attached value).
            let chars: Vec<char> = short_part.chars().collect();
            if chars.len() == 1 {
                let spec = find_spec_by_short(chars[0])
                    .ok_or_else(|| ParseError::new(1, format!("Unknown option -{}", chars[0])))?
                    .clone();
                let value = match spec.arg {
                    Some(_) => {
                        if let Some((_, next)) = iter.next() {
                            Some(next.clone())
                        } else {
                            return Err(ParseError::new(1, format!("-{} requires a value", spec.short.unwrap_or(' '))));
                        }
                    }
                    None => Some("true".into()),
                };
                set_value(&mut opts, spec.name, value)?;
            } else {
                // First char is the option; remaining are attached value.
                let first = chars[0];
                let rest = short_part[1..].to_owned();
                let spec = find_spec_by_short(first)
                    .ok_or_else(|| ParseError::new(1, format!("Unknown option -{}", first)))?
                    .clone();
                let value = match spec.arg {
                    Some(_) => Some(rest),
                    None => {
                        if rest.chars().any(|c| !matches!(c, 'b' | 'd' | 'n' | 's' | 'E' | 'a')) {
                            // Single letter boolean combos like `-bn`.
                            let mut combined = String::new();
                            for c in chars.iter() {
                                let sub = find_spec_by_short(*c)
                                    .ok_or_else(|| ParseError::new(1, format!("Unknown option -{}", c)))?
                                    .clone();
                                if sub.arg.is_some() {
                                    return Err(ParseError::new(1, format!("-{} requires a value and cannot be combined", c)));
                                }
                                combined.push(*c);
                            }
                            Some(combined)
                        } else {
                            return Err(ParseError::new(1, format!("-{} does not take a value", first)));
                        }
                    }
                };
                set_value(&mut opts, spec.name, value)?;
            }
        } else {
            opts.paths.push(arg.clone());
        }
    }

    // First positional becomes the transform if not specified.
    if opts.transform.is_none() && !opts.paths.is_empty() {
        // In the original argsParser, the transform is the first positional
        // *if* the first positional looks like a transform file (ends with
        // .js, .ts, .tsx). Otherwise transform must be passed via -t/--transform.
        let first = &opts.paths[0];
        let lower = first.to_lowercase();
        if lower.ends_with(".js") || lower.ends_with(".mjs") || lower.ends_with(".cjs")
            || lower.ends_with(".ts") || lower.ends_with(".tsx") {
            opts.transform = Some(opts.paths.remove(0));
        }
    }

    if opts.worker_count.is_some() && opts.run_in_band {
        return Err(ParseError::new(1, "Both --run-in-band and --worker cannot be used at the same time."));
    }

    Ok(opts)
}

/// Convenience: parse argv (skipping the program name) and return either the
/// options or a structured error.
pub fn parse_argv(argv: &[String]) -> Result<Options, ParseError> {
    parse(argv)
}

/// `throwError`-equivalent helper. Caller prints the message and the help text
/// if `help` is true, then exits with `code`.
pub fn report_error(err: &ParseError) -> (i32, String) {
    let mut out = err.message.clone();
    if err.help {
        out.push('\n');
        out.push_str(&build_help());
    }
    (err.code, out)
}"}

{"security_risk":"LOW","summary":"Create ignore patterns module","command":"create","file_text":"//! Picomatch-compatible ignore-pattern handling.
//!
//! Mirrors `src/ignoreFiles.js`:
//!   * patterns without `/` are also tested as `**/<pattern>`
//!   * patterns ending in `/` get an extra `**/<pattern>**` and `<pattern>**`
//!   * paths with leading `./` or `../` are also tested with those prefixes
//!     stripped (matches picomatch's behavior for relative sources)
//!   * the original pattern is always added verbatim
//!
//! Implementation: we hand-roll a small, well-defined subset of picomatch
//! sufficient for jscodeshift's tests and standard gitignore patterns. We
//! deliberately avoid pulling in a heavy glob crate.

use std::path::Path;

/// Internal storage of compiled patterns.
#[derive(Debug, Default, Clone)]
pub struct IgnoreSet {
    raw_patterns: Vec<String>,
    rules: Vec<CompiledRule>,
}

#[derive(Debug, Clone)]
struct CompiledRule {
    regex: regex::Regex,
}

impl IgnoreSet {
    pub fn new() -> Self { IgnoreSet::default() }

    /// Add a single pattern string (no `#` prefix or empty handling here).
    pub fn push(&mut self, val: &str) {
        let mut raw_patterns: Vec<String> = vec![val.to_owned()];
        if !val.contains('/') {
            raw_patterns.push(format!("**/{}", val));
        } else if val.ends_with('/') {
            raw_patterns.push(format!("**/{}{}", val, "**"));
            raw_patterns.push(format!("{}{}", val, "**"));
        }
        for p in raw_patterns {
            if !self.raw_patterns.contains(&p) {
                self.raw_patterns.push(p.clone());
                if let Some(re) = compile_pattern(&p) {
                    self.rules.push(CompiledRule { regex: re });
                }
            }
        }
    }

    /// Returns true if any of the registered patterns matches `path`.
    pub fn is_match<P: AsRef<Path>>(&self, path: P) -> bool {
        let path_str = match path.as_ref().to_str() {
            Some(s) => s,
            None => return false,
        };
        let normalized = strip_traversal_prefix(path_str);
        for rule in &self.rules {
            if rule.regex.is_match(path_str) {
                return true;
            }
            if normalized != path_str && rule.regex.is_match(normalized) {
                return true;
            }
        }
        false
    }
}

fn strip_traversal_prefix(s: &str) -> &str {
    let bytes = s.as_bytes();
    let mut i = 0;
    loop {
        if bytes.len() >= i + 3 && &bytes[i..i + 3] == b"../" {
            i += 3;
        } else if bytes.len() >= i + 2 && &bytes[i..i + 2] == b"./" {
            i += 2;
        } else {
            break;
        }
    }
    &s[i..]
}

/// Compile a glob-style pattern to a regular expression.
fn compile_pattern(pat: &str) -> Option<regex::Regex> {
    let mut out = String::with_capacity(pat.len() * 2);
    out.push('^');
    let chars: Vec<char> = pat.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '*' {
            // `**` -> match anything including separators, `*` -> match anything except `/`.
            if i + 1 < chars.len() && chars[i + 1] == '*' {
                out.push_str(".*");
                i += 2;
                // After `**/` we collapse the trailing slash into the glob.
                if i < chars.len() && chars[i] == '/' {
                    i += 1;
                }
            } else {
                out.push_str("[^/]*");
                i += 1;
            }
        } else if c == '?' {
            out.push_str("[^/]");
            i += 1;
        } else if c == '[' {
            // Character class; copy until matching ']'.
            out.push('[');
            i += 1;
