            out.push_str(&regex::escape(&chars[i + 1..i + 2]));
            i += 2;
        } else if matches!(c, '.' | '(' | ')' | '+' | '|' | '^' | '$' | '{' | '}' | '#') {
            out.push('\\');
            out.push(c);
            i += 1;
        } else {
            out.push(c);
            i += 1;
        }
    }
