//!
//! Mirrors `src/ignoreFiles.js`:
//!   * patterns without `/` are also tested as `**/<pattern>`
//!   * patterns ending in `/` get an extra `**/<pattern>**` and `<pattern>**`
//!   * paths with leading `./` or `../` are also tested with those prefixes
//!     stripped (matches picomatch's behavior for relative sources)
//!   * the original pattern is always added verbatim
//!
//! Implementation: hand-rolled glob compiler so we don't depend on a heavy
//! regex/glob crate. The supported subset is sufficient for jscodeshift's
//! usage (gitignore-style patterns with `*`, `**`, `?`, `[...]`, escapes).

use std::path::Path;

#[derive(Debug, Default, Clone)]
pub struct IgnoreSet {
    rules: Vec<CompiledRule>,
}

#[derive(Debug, Clone)]
struct CompiledRule {
    regex: regex::Regex,
}

impl IgnoreSet {
    pub fn new() -> Self { IgnoreSet::default() }

    pub fn push(&mut self, val: &str) {
        let mut patterns: Vec<String> = vec![val.to_owned()];
        if !val.contains('/') {
            patterns.push(format!("**/{}", val));
        } else if val.ends_with('/') {
            patterns.push(format!("**/{}{}", val, "**"));
            patterns.push(format!("{}{}", val, "**"));
        }
        for p in patterns {
            if let Some(re) = compile_pattern(&p) {
                self.rules.push(CompiledRule { regex: re });
            }
        }
    }

    pub fn is_match<P: AsRef<Path>>(&self, path: P) -> bool {
        let path_str = match path.as_ref().to_str() {
            Some(s) => s,
            None => return false,
        };
        let normalized = strip_traversal_prefix(path_str);
        for rule in &self.rules {
            if rule.regex.is_match(path_str) {
                return true;
            }
            if normalized != path_str && rule.regex.is_match(normalized) {
                return true;
            }
        }
        false
    }
}

fn strip_traversal_prefix(s: &str) -> &str {
    let bytes = s.as_bytes();
    let mut i = 0;
    loop {
        if bytes.len() >= i + 3 && &bytes[i..i + 3] == b"../" {
            i += 3;
        } else if bytes.len() >= i + 2 && &bytes[i..i + 2] == b"./" {
            i += 2;
        } else {
            break;
        }
    }
    &s[i..]
}

fn compile_pattern(pat: &str) -> Option<regex::Regex> {
    let mut out = String::with_capacity(pat.len() * 2);
    out.push('^');
    let chars: Vec<char> = pat.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '*' {
            if i + 1 < chars.len() && chars[i + 1] == '*' {
                out.push_str(".*");
                i += 2;
                if i < chars.len() && chars[i] == '/' {
                    i += 1;
                }
            } else {
                out.push_str("[^/]*");
                i += 1;
            }
        } else if c == '?' {
            out.push_str("[^/]");
            i += 1;
        } else if c == '[' {
            out.push('[');
            i += 1;
            if i < chars.len() && (chars[i] == '!' || chars[i] == '^') {
                out.push('^');
                i += 1;
            }
            while i < chars.len() && chars[i] != ']' {
                if chars[i] == '\\' && i + 1 < chars.len() {
                    out.push(chars[i]);
                    out.push(chars[i + 1]);
                    i += 2;
                } else {
                    out.push(chars[i]);
                    i += 1;
                }
            }
            if i < chars.len() && chars[i] == ']' {
                out.push(']');
                i += 1;
            }
        } else if c == '\\' && i + 1 < chars.len() {
            let lit = chars[i + 1];
            out.push_str(&regex::escape(&lit.to_string()));
            i += 2;
        } else if matches!(c, '.' | '(' | ')' | '+' | '|' | '^' | '$' | '{' | '}' | '#') {
            out.push('\\');
            out.push(c);
            i += 1;
        } else {
            out.push(c);
            i += 1;
        }
    }
    out.push('$');
    regex::Regex::new(&out).ok()
}

pub fn add_ignore_from_files(set: &mut IgnoreSet, paths: &[String]) {
    for p in paths {
        if let Ok(content) = std::fs::read_to_string(p) {
            for line in content.lines() {
                let trimmed = line.trim();
                if !trimmed.is_empty() && !trimmed.starts_with('#') {
                    set.push(trimmed);
                }
            }
        }
    }
}

pub fn add_ignore_patterns(set: &mut IgnoreSet, patterns: &[String]) {
    for p in patterns {
        let trimmed = p.trim();
        if !trimmed.is_empty() && !trimmed.starts_with('#') {
            set.push(trimmed);
        }
    }
}

