{"security_risk":"LOW","summary":"Create file discovery module","path":"/workspace/src/rs/files.rs","file_text":"//! File discovery that mirrors `src/dirFiles.js`.
//!
//! For each input path the user supplied:
//!   * if it's a file, it's included as-is
//!   * if it's a directory, it's walked recursively and any file whose
//!     extension matches the configured list is included
//!
//! Hidden directories (those whose first segment starts with `.`) are skipped
//! to match the behavior of the JavaScript implementation, which used a
//! `hidden: false` walker.

use std::path::{Path, PathBuf};

use walkdir::WalkDir;

use crate::ignore::IgnoreSet;
use crate::options::Options;

#[derive(Debug)]
pub struct FilePlan {
    /// Absolute paths to files that should be transformed.
    pub files: Vec<String>,
    /// Warnings emitted during discovery (e.g. missing paths).
    pub warnings: Vec<String>,
}

/// Discover files for the given CLI options.
pub fn collect_files(opts: &Options, ignore_set: &IgnoreSet) -> FilePlan {
    let mut files = Vec::new();
    let mut warnings = Vec::new();
    for input in &opts.paths {
        let p = PathBuf::from(input);
        if !p.exists() {
            warnings.push(format!("Path not found: {}", input));
            continue;
        }
        if p.is_file() {
            add_file(&p, opts, ignore_set, &mut files);
        } else if p.is_dir() {
            walk_dir(&p, opts, ignore_set, &mut files);
        } else {
            // Symlink or special: treat as file if exists.
            add_file(&p, opts, ignore_set, &mut files);
        }
    }
    FilePlan { files, warnings }
}

fn add_file(p: &Path, opts: &Options, ignore_set: &IgnoreSet, files: &mut Vec<String>) {
    let display = p.to_string_lossy().to_string();
    if ignore_set.is_match(&display) {
        return;
    }
    if !matches_extension(p, &opts.extensions) {
        return;
    }
    files.push(display);
}

fn walk_dir(dir: &Path, opts: &Options, ignore_set: &IgnoreSet, files: &mut Vec<String>) {
    for entry in WalkDir::new(dir).follow_links(false) {
        let entry = match entry {
            Ok(e) => e,
            Err(e) => continue,
        };
        if !entry.file_type().is_file() {
            continue;
        }
        // Skip hidden files (paths with a `.`-prefixed segment), matching the
        // original walker.
        if has_hidden_segment(entry.path()) {
            continue;
        }
        let display = entry.path().to_string_lossy().to_string();
        if ignore_set.is_match(&display) {
            continue;
        }
        if !matches_extension(entry.path(), &opts.extensions) {
            continue;
        }
        files.push(display);
    }
}

fn has_hidden_segment(p: &Path) -> bool {
    p.components().any(|c| {
        c.as_os_str()
            .to_str()
            .map(|s| s.starts_with('.') && s != "." && s != "..")
            .unwrap_or(false)
    })
}

fn matches_extension(p: &Path, extensions: &[String]) -> bool {
    let ext = match p.extension().and_then(|s| s.to_str()) {
        Some(e) => e,
        None => return false,
    };
    extensions.iter().any(|x| x == ext)
}"}

{"security_risk":"LOW","summary":"Create message protocol module","path":"/workspace/src/rs/message.rs","file_text":"//! Line-delimited JSON protocol between the Rust CLI and the JS worker bridge.
//!
//! The Rust CLI sends a single `{ kind: "config", ... }` envelope at startup
//! (containing the transform path, options, and the initial batch of files).
//! The worker emits one JSON object per status update, terminated by
//! `{ kind: "done" }`.

use serde::{Deserialize, Serialize};
use serde_json::Value;

/// Envelope sent from Rust to the worker at startup. The same object is
/// re-emitted for each subsequent batch with `kind = "batch"`.
#[derive(Debug, Clone, Serialize)]
pub struct StartMessage {
    #[serde(rename = "kind")]
    pub kind: &'static str,
    #[serde(rename = "transform")]
    pub transform: String,
    #[serde(rename = "options")]
    pub options: Value,
    #[serde(rename = "files")]
    pub files: Vec<String>,
    #[serde(rename = "batchSize")]
    pub batch_size: usize,
    #[serde(rename = "verbose")]
    pub verbose: u8,
    #[serde(rename = "dry")]
    pub dry: bool,
    #[serde(rename = "babel")]
    pub babel: bool,
    #[serde(rename = "print")]
    pub print: bool,
    #[serde(rename = "runAsync")]
    pub run_async: bool,
    #[serde(rename = "packageRoot")]
    pub package_root: String,
}

impl StartMessage {
    pub fn for_config(opts: &crate::options::Options, package_root: String, transform: &str, batch_size: usize, files: Vec<String>) -> Self {
        let mut o = serde_json::Map::new();
        o.insert("parser".into(), Value::String(opts.parser.clone()));
        if let Some(ref p) = opts.parser_options {
            o.insert("parserOptions".into(), match serde_json::from_str::<Value>(p) {
                Ok(v) => v,
                Err(_) => Value::Null,
            });
        } else {
            o.insert("parserOptions".into(), Value::Null);
        }
        o.insert("transformOptions".into(), match serde_json::from_str::<Value>(&opts.transform_options) {
            Ok(v) => v,
            Err(_) => Value::Object(serde_json::Map::new()),
        });
        o.insert("extensions".into(), serde_json::to_value(&opts.extensions).unwrap_or(Value::Array(vec![])));
        StartMessage {
            kind: "config",
            transform: transform.to_owned(),
            options: Value::Object(o),
            files,
            batch_size,
            verbose: opts.verbose,
            dry: opts.dry,
            babel: opts.babel,
            print: opts.print,
            run_async: opts.run_async,
            package_root,
        }
    }

    pub fn for_batch(&self, files: Vec<String>) -> BatchMessage {
        BatchMessage {
            kind: "batch",
            files,
        }
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct BatchMessage {
    #[serde(rename = "kind")]
    pub kind: &'static str,
    #[serde(rename = "files")]
    pub files: Vec<String>,
}

/// Messages the worker can emit back to the Rust CLI.
#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "kind")]
pub enum WorkerEvent {
    #[serde(rename = "status")]
    Status {
        status: String,
        #[serde(default)]
        file: Option<String>,
        #[serde(default)]
        msg: Option<String>,
    },
    #[serde(rename = "report")]
    Report {
        #[serde(default)]
        file: Option<String>,
        msg: String,
    },
    #[serde(rename = "update")]
    Update {
        name: String,
        quantity: i64,
    },
    #[serde(rename = "print")]
    Print {
        file: String,
        content: String,
    },
    #[serde(rename = "free")]
    Free,
    #[serde(rename = "done")]
    Done,
    #[serde(rename = "error")]
    Error {
        msg: String,
        #[serde(default)]
        stack: Option<String>,
    },
    #[serde(other)]
    Unknown,
}

impl WorkerEvent {
    pub fn parse_line(line: &str) -> Option<WorkerEvent> {
        serde_json::from_str::<WorkerEvent>(line).ok()
    }
}"}

{"security_risk":"LOW","summary":"Create worker subprocess module","command":"create","path":"/workspace/src/rs/worker.rs","file_text":"//! Manages a single JS bridge worker process: spawning Node, communicating
//! via line-delimited JSON over stdio, and reading back worker events.

use std::io::{BufRead, BufReader, Write};
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};
use std::sync::mpsc::{channel, Receiver};

use crate::message::{BatchMessage, StartMessage, WorkerEvent};

/// A single spawned worker.
pub struct WorkerProc {
    child: Child,
    stdin: ChildStdin,
    pub receiver: Receiver<WorkerEvent>,
    pub finished: bool,
}

impl WorkerProc {
    pub fn spawn(node_executable: &str, bridge_path: &str, start: &StartMessage) -> std::io::Result<WorkerProc> {
        let mut cmd = Command::new(node_executable);
        cmd.arg(bridge_path)
            .arg("--kind=config")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        cmd.env("FORCE_COLOR", "1");
        cmd.env("NODE_NO_WARNINGS", "1");

        let mut child = cmd.spawn()?;
        let mut stdin = child.stdin.take().expect("worker stdin");
        let stdout = child.stdout.take().expect("worker stdout");

        // Send the initial config message.
        let payload = serde_json::to_string(start).unwrap_or_default();
        writeln!(stdin, "{}", payload)?;
        stdin.flush()?;

        let (tx, rx) = channel::<WorkerEvent>();
        spawn_reader(stdout, tx);

        Ok(WorkerProc {
            child,
            stdin,
            receiver: rx,
            finished: false,
        })
    }

    pub fn send_batch(&mut self, batch: &BatchMessage) -> std::io::Result<()> {
        let payload = serde_json::to_string(batch).unwrap_or_default();
        writeln!(self.stdin, "{}", payload)?;
        self.stdin.flush()?;
        Ok(())
    }

    pub fn wait_exit(&mut self) -> std::io::Result<std::process::ExitStatus> {
        self.child.wait()
    }

    pub fn kill(&mut self) -> std::io::Result<()> {
        self.child.kill()
    }
}

fn spawn_reader(stdout: ChildStdout, tx: std::sync::mpsc::Sender<WorkerEvent>) {
    let reader = BufReader::new(stdout);
    std::thread::spawn(move || {
        for line in reader.lines() {
            let line = match line {
                Ok(l) => l,
                Err(_) => break,
            };
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }
            if let Some(event) = WorkerEvent::parse_line(trimmed) {
                if tx.send(event).is_err() {
                    break;
                }
            }
        }
    });
}

/// Try to discover a Node executable. We probe a couple of well-known names
/// (in addition to whatever the caller suggests) to make the CLI resilient
/// when run outside a PATH-bearing shell.
pub fn find_node(preferred: Option<&str>) -> Option<String> {
    let candidates: Vec<String> = match preferred {
        Some(p) => vec![p.to_owned(), "node".into()],
        None => vec!["node".into()],
    };
    for name in candidates {
        if Command::new(&name).arg("--version").output().is_ok() {
            return Some(name);
        }
    }
    None
}"}

