//! helper methods in `src/Runner.js`.

use crate::colors;

pub struct Stats {
    pub ok: u64,
    pub nochange: u64,
    pub skip: u64,
    pub error: u64,
    pub total: u64,
}

impl Stats {
    pub fn new() -> Self {
        Stats { ok: 0, nochange: 0, skip: 0, error: 0, total: 0 }
    }
}

/// Print the outcome of running a transform on a single file, exactly matching
/// the format `Runner.js` produced: `RESULT  (status)  file`.
pub fn print_status(file: &str, status: &str, msg: Option<&str>) {
    let label = match status {
        "ok" => colors::green("OK"),
        "ok!" => colors::green("OK!"),
        "noop" => colors::cyan("NOOP"),
        "skip" => colors::yellow("SKIP"),
        "error" => colors::bg_red(&colors::white("ERROR")),
        other => other.to_owned(),
    };
    let body = match msg {
        Some(m) => format!("{} {} {}", label, file, colors::gray(m)),
        None => format!("{} {}", label, file),
    };
    println!("{}", body);
}

pub fn print_report(file: &str, msg: &str) {
    println!("{} {}", colors::bg_yellow(&colors::bold("REPORT")), format!("{}{}{}{}", colors::gray(file), colors::gray(" "), colors::bold(msg), ""));
}

pub fn print_summary(stats: &Stats, elapsed_ms: u128) {
    let secs = elapsed_ms as f64 / 1000.0;
    let total = stats.total.max(1);
    println!();
    println!(
        "{} {}",
        colors::bold("All done."),
        format!(
            "Results: {} ok, {} nochange, {} skip, {} error, {} total ({}s)",
            stats.ok, stats.nochange, stats.skip, stats.error, stats.total, secs
        )
    );
    println!(
        "Time: ~{:.2}s ({:.1}s/file, parallel {})",
        secs,
        secs / total as f64,
        colors::bold("0")
    );
}"}

{"security_risk":"LOW","summary":"Create runner module","command":"create","path":"/workspace/src/rs/runner.rs","file_text":"//! Top-level orchestrator: picks a worker count, spawns bridges, and feeds
//! them batches of files. Mirrors `Runner.js` but with a JS bridge doing the
//! actual transform application.

use std::sync::{Arc, Mutex};
use std::time::Instant;

use crate::message::{BatchMessage, StartMessage, WorkerEvent};
use crate::options::Options;
use crate::output::{print_report, print_status, print_summary, Stats};
use crate::worker::{find_node, WorkerProc};

const DEFAULT_BATCH_SIZE: usize = 10;

pub struct RunResult {
    pub stats: Stats,
    pub elapsed_ms: u128,
}

pub struct RunContext<'a> {
    pub opts: &'a Options,
    pub package_root: &'a str,
    pub bridge_path: &'a str,
    pub transform_path: &'a str,
    pub files: &'a [String],
}

pub fn run(ctx: RunContext<'_>) -> Result<RunResult, String> {
    let RunContext { opts, package_root, bridge_path, transform_path, files } = ctx;
    let start = Instant::now();
    if files.is_empty() {
        let stats = Stats::new();
        return Ok(RunResult { stats, elapsed_ms: start.elapsed().as_millis() });
    }

    let node = find_node(opts.stdin.then_some("node")).or_else(|| find_node(None))
        .ok_or_else(|| "Unable to locate the `node` executable. Install Node.js to run transforms.".to_owned())?;

    let worker_count = determine_worker_count(opts, files.len());
    let batch_size = std::cmp::min(DEFAULT_BATCH_SIZE, std::cmp::max(1, files.len() / worker_count));

    let stats = Arc::new(Mutex::new(Stats::new()));
    let mut workers: Vec<WorkerProc> = Vec::with_capacity(worker_count);

    // Pre-split files into batches, then assign one initial batch per worker.
    let batches: Vec<Vec<String>> = files.chunks(batch_size).map(|c| c.iter().cloned().collect()).collect();
    let mut iter = batches.into_iter();
    for _ in 0..worker_count {
        let batch = iter.next().unwrap_or_default();
        let msg = StartMessage::for_config(opts, package_root.to_owned(), transform_path, batch_size, batch);
        let w = WorkerProc::spawn(&node, bridge_path, &msg)
            .map_err(|e| format!("Failed to spawn worker ({}): {}", node, e))?;
        workers.push(w);
    }

    // Distribute remaining batches as workers become free.
    let mut remaining = iter.peekable();
    while remaining.peek().is_some() {
        let mut progressed = false;
        for w in workers.iter_mut() {
            if let Ok(event) = w.receiver.try_recv() {
                progressed = true;
                if matches_event(&event, &stats, opts.print) {
                    if let Some(next_batch) = remaining.next() {
                        let batch_msg = BatchMessage { kind: "batch", files: next_batch };
                        let _ = w.send_batch(&batch_msg);
                    }
                }
                if matches!(event, WorkerEvent::Done) {
                    w.finished = true;
                }
            }
        }
        if !progressed {
            // Brief sleep to avoid burning CPU; equivalent to the JS runner's
            // `setImmediate` yield.
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
    }

    // Drain remaining messages after all batches are dispatched.
    drain(&mut workers, &stats, opts.print);

    let stats_snapshot = stats.lock().unwrap().clone();
    Ok(RunResult {
        stats: stats_snapshot,
        elapsed_ms: start.elapsed().as_millis(),
    })
}

fn determine_worker_count(opts: &Options, file_count: usize) -> usize {
    if opts.run_in_band {
        return 1;
    }
    let requested = opts.worker_count.unwrap_or_else(|| {
        if opts.cpus > 0 { opts.cpus } else { 1 }
    });
    std::cmp::max(1, std::cmp::min(requested.max(1), file_count.max(1)))
}

fn drain(workers: &mut Vec<WorkerProc>, stats: &Arc<Mutex<Stats>>, print_mode: bool) {
    let mut alive: Vec<usize> = (0..workers.len()).collect();
    while !alive.is_empty() {
        let mut progressed = false;
        let mut next_alive = Vec::with_capacity(alive.len());
        for idx in &alive {
            let w = &mut workers[*idx];
            match w.receiver.recv_timeout(std::time::Duration::from_millis(50)) {
                Ok(event) => {
                    progressed = true;
                    let _ = matches_event(&event, stats, print_mode);
                    if matches!(event, WorkerEvent::Done) {
                        w.finished = true;
                    } else {
                        next_alive.push(*idx);
                    }
                }
                Err(_) => next_alive.push(*idx),
            }
        }
        alive = next_alive;
        if !progressed {
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
    }
    for w in workers.iter_mut() {
        let _ = w.wait_exit();
    }
}

fn matches_event(event: &WorkerEvent, stats: &Arc<Mutex<Stats>>, print_mode: bool) -> bool {
    match event {
        WorkerEvent::Status { status, file, msg } => {
            let mut s = stats.lock().unwrap();
            s.total += 1;
            match status.as_str() {
                "ok" | "ok!" => s.ok += 1,
                "noop" => s.nochange += 1,
                "skip" => s.skip += 1,
                "error" => s.error += 1,
                _ => {}
            }
            drop(s);
            if let Some(f) = file {
                print_status(f, status, msg.as_deref());
            }
        }
        WorkerEvent::Report { file, msg } => {
            if let Some(f) = file {
                print_report(f, msg);
            }
        }
        WorkerEvent::Update { name, quantity } => {
            // Currently we only surface errors; future stats could be added.
            let mut s = stats.lock().unwrap();
            if name == "errors" {
                s.error += *quantity as u64;
            }
        }
        WorkerEvent::Print { file, content } => {
            if print_mode {
                println!("\n\u{1b}[7m {}\u{1b}[0m\n{}", file, content);
            }
        }
        WorkerEvent::Error { msg, .. } => {
            eprintln!("worker error: {}", msg);
        }
        WorkerEvent::Free => {}
        WorkerEvent::Done => {}
        WorkerEvent::Unknown => {}
    }
    true
}

pub fn report_summary(result: &RunResult) {
    print_summary(&result.stats, result.elapsed_ms);
}"}

