use crate::options::{build_help, Options};
use crate::package_info::locate_package_root;
use crate::runner::{report_summary, run, RunContext};

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().skip(1).collect();
    match run_cli(&argv) {
        Ok(code) => ExitCode::from(code as u8),
        Err(msg) => {
            eprintln!("{}", msg);
            ExitCode::from(1)
        }
    }
}

fn run_cli(argv: &[String]) -> Result<i32, String> {
    // Special-case `help` and `version` before fully parsing, since the JS
    // version printed them regardless of the validity of other args.
    let opts = match parse(argv) {
        Ok(o) => o,
        Err(e) => {
            if e.help {
                eprintln!("{}", build_help());
                return Ok(e.code as i32);
            }
            return Err(format!("Error: {}", e.message));
        }
    };

    let exe_path = env::current_exe().map_err(|e| format!("Unable to locate executable: {}", e))?;
    let package_root = locate_package_root(&exe_path)
        .or_else(|| env::current_dir().ok().and_then(|c| locate_package_root(&c)))
        .ok_or_else(|| "Unable to locate jscodeshift package root. Please reinstall jscodeshift.".to_owned())?;

    if opts.version {
        let version = package_info::package_version(&package_root);
        println!("{}", version);
        return Ok(0);
    }
    if opts.help || argv.is_empty() {
        println!("{}", build_help());
        return Ok(0);
    }

    let transform_path = opts.transform.clone()
        .ok_or_else(|| "Missing transform file. Use -t or pass the transform as the first argument.".to_owned())?;

    let bridge_path = package_root.join("bridge").join("transform-host.js");
    if !bridge_path.exists() {
        return Err(format!("Bridge module not found at {}. The package may be incomplete.", bridge_path.display()));
    }

    // Build ignore set from CLI args + user-supplied config files.
    let mut ignore_set = IgnoreSet::new();
    add_ignore_patterns(&mut ignore_set, &opts.ignore_pattern);
    add_ignore_from_files(&mut ignore_set, &opts.ignore_config);
    if opts.gitignore {
        if let Some(p) = find_gitignore(&package_root) {
            add_ignore_from_files(&mut ignore_set, &[p]);
        }
    }

    // Optional `.gitignore` discovery inside each input dir.
    if opts.gitignore {
        for input in &opts.paths {
            let p = Path::new(input);
            if p.is_dir() {
                let gi = p.join(".gitignore");
                if gi.exists() {
                    add_ignore_from_files(&mut ignore_set, &[gi.to_string_lossy().to_string()]);
                }
            }
        }
    }

    // `--stdin` reads a single file from stdin and prints the transform result.
    if opts.stdin {
        return run_stdin_mode(&opts, &package_root, &bridge_path, &transform_path);
    }

    let plan = collect_files(&opts, &ignore_set);
    for w in &plan.warnings {
        eprintln!("{}", w);
    }
    if plan.files.is_empty() {
        eprintln!("No files selected by the provided arguments.");
        return Ok(0);
    }

    let ctx = RunContext {
        opts: &opts,
        package_root: &package_root.to_string_lossy(),
        bridge_path: &bridge_path.to_string_lossy(),
        transform_path: &transform_path,
        files: &plan.files,
    };
    let result = run(ctx).map_err(|e| format!("Error: {}", e))?;
    report_summary(&result);
    Ok(if result.stats.error > 0 { 1 } else { 0 })
