fn run_stdin_mode(opts: &Options, package_root: &Path, bridge_path: &Path, transform_path: &str) -> Result<i32, String> {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).map_err(|e| format!("Failed to read stdin: {}", e))?;
    let node = crate::worker::find_node(Some("node"))
        .ok_or_else(|| "Unable to locate the `node` executable.".to_owned())?;

    let temp = std::env::temp_dir().join("jscodeshift-stdin.js");
    std::fs::write(&temp, &buf).map_err(|e| format!("Failed to write temp file: {}", e))?;
    let files = vec![temp.to_string_lossy().to_string()];
    let msg = message::StartMessage::for_config(opts, package_root.to_string_lossy().to_string(), transform_path, 1, files);

    let mut worker = worker::WorkerProc::spawn(&node, &bridge_path.to_string_lossy(), &msg)
        .map_err(|e| format!("Failed to spawn worker: {}", e))?;

    while let Ok(event) = worker.receiver.recv_timeout(std::time::Duration::from_millis(100)) {
        match event {
            message::WorkerEvent::Print { content, .. } => {
                print!("{}", content);
            }
            message::WorkerEvent::Error { msg, stack } => {
                eprintln!("error: {}", msg);
                if let Some(s) = stack { eprintln!("{}", s); }
                let _ = std::fs::remove_file(&temp);
                return Ok(1);
            }
            message::WorkerEvent::Done => break,
            _ => {}
        }
    }
    let _ = std::fs::remove_file(&temp);
    Ok(0)
}

fn find_gitignore(package_root: &Path) -> Option<String> {
    let p = package_root.join(".gitignore");
    if p.exists() { Some(p.to_string_lossy().to_string()) } else { None }
}"}

