/// Drain the worker's stderr stream. The bridge writes the result of any
/// `--print` transform to stderr (its stdout is reserved for status JSON),
/// and we forward those bytes to the parent process's stdout so the user
/// sees the printed transform output.
fn spawn_stderr_drain(stderr: std::process::ChildStderr) {
    use std::io::Read;
    let mut reader = BufReader::new(stderr);
    let mut stdout = std::io::stdout();
    std::thread::spawn(move || {
        let mut buf = [0u8; 4096];
        loop {
            match reader.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    let _ = stdout.write_all(&buf[..n]);
                    let _ = stdout.flush();
                }
                Err(_) => break,
            }
        }
    });
}"}

